#include <stdio.h>
#include <stdlib.h>

int main(){
    int N; scanf("%d", &N);
    if(N<=0) return 0;
    long long *fib = malloc(N * sizeof *fib);
    fib[0] = 0; if(N>1) fib[1] = 1;
    for(int i=2;i<N;i++) fib[i] = fib[i-1] + fib[i-2];
    for(int i=0;i<N;i++) printf("%lld ", fib[i]);
    printf("\n");
    free(fib);
    return 0;
}

