#include <stdio.h>

// Simple algorithm: find the maximum of three numbers
int main() {
    int a, b, c, max;
    printf("Enter three integers: ");
    scanf("%d %d %d", &a, &b, &c);
    // Step 1: assume a is max
    max = a;
    // Step 2: compare with b
    if (b > max) max = b;
    // Step 3: compare with c
    if (c > max) max = c;
    printf("Maximum = %d\n", max);
    return 0;
}

