#include <stdio.h>
int main() {
    int n;
    printf("Enter a number: ");
    scanf("%d", &n);
    // Logical part: check even/odd
    if (n % 2 == 0) {
        printf("%d is Even\n", n);
    } else {
        printf("%d is Odd\n", n);
    }
    // Numerical part: sum of first n natural numbers
    long long sum = 0; // use long long for safety
    for (int i = 1; i <= n; ++i) {
        sum += i;
    }
    printf("Sum of first %d numbers = %lld\n", n, sum);
    return 0;
}
/* Important lines:
   - `n % 2 == 0` decides even/odd (logical).
   - Loop accumulates `sum` (numerical).
*/

