typedef struct { void **data; int top; int capacity; } Stack;
void push(Stack *s, void *item){ if(s->top==s->capacity){ s->capacity*=2; s->data=realloc(s->data, s->capacity*sizeof(void*)); } s->data[s->top++]=item; }
void *pop(Stack *s){ if(s->top==0) return NULL; return s->data[--s->top]; }

