#include <stdio.h>

// Function that returns the sum of two integers
int add(int a, int b) {
    return a + b;               // simple arithmetic
}

int main() {
    // 1. Array of 5 integers
    int arr[5] = {10, 20, 30, 40, 50};

    // 2. Pointer to the first element of the array
    int *p = arr;                 // arr decays to &arr[0]
    printf("First element via pointer: %d\n", *p);

    // 3. Pointer arithmetic – access 3rd element
    printf("Third element via pointer arithmetic: %d\n", *(p + 2));

    // 4. Function pointer
    int (*fp)(int, int) = add;    // fp points to add()
    int result = fp(7, 8);        // call through pointer
    printf("Result from function pointer: %d\n", result);
    return 0;
}

#include <stdio.h>

// Define a struct for a student record
typedef struct {
    int id;
    char name[30];
    float gpa;
} Student;

// Define a union that can hold either an int or a float
union Number {
    int i;
    float f;
};

// Define an enum for grade letters
enum Grade { A = 4, B = 3, C = 2, D = 1, F = 0 };

int main() {
    Student s = {101, "Anita", 9.1f};
    printf("Student: %d, %s, %.2f\n", s.id, s.name, s.gpa);

    union Number n;
    n.i = 10;               // store int
    printf("Union as int: %d\n", n.i);
    n.f = 3.14f;            // now store float, int value is overwritten
    printf("Union as float: %.2f\n", n.f);

    enum Grade g = B;
    printf("Enum Grade B value: %d\n", g);
    return 0;
}

