void reverse(int *a, int n) {
    int *p = a;          // start pointer
    int *q = a + n - 1;  // end pointer
    while (p < q) {
        int tmp = *p;
        *p = *q;
        *q = tmp;
        ++p;   // move forward
        --q;   // move backward (pre‑decrement)
    }
}
