int main(void) {
    // Print numbers until we encounter a multiple of 7
    for (int i = 1; i <= 20; ++i) {
        if (i % 7 == 0) {
            printf("Found %d, breaking out of loop.\n", i);
            break; // exits the for‑loop immediately
        }
        printf("%d ", i);
    }
    printf("Loop ended.\n");
    return 0;
}
