#include <stdio.h>
#include <math.h>

// Classic number utilities – prime, palindrome, Armstrong, perfect, reverse, sum of digits, GCD/LCM
int main(void) {
    int n;                     // input number
    printf("Enter an integer: ");
    scanf("%d", &n);

    // ---------- Prime ----------
    int isPrime = 1;           // assume prime
    if (n < 2) isPrime = 0;
    for (int i = 2; i * i <= n; ++i) {
        if (n % i == 0) { isPrime = 0; break; }
    }
    printf("%d is %sprime\n", n, isPrime ? "" : "not ");

    // ---------- Palindrome ----------
    int rev = 0, temp = n;
    while (temp > 0) {
        rev = rev * 10 + temp % 10;
        temp /= 10;
    }
    printf("%d is %spalindrome\n", n, (rev == n) ? "" : "not ");

    // ---------- Armstrong ----------
    int digits = 0, sum = 0, t = n;
    while (t > 0) { digits++; t /= 10; }
    t = n;
    while (t > 0) {
        int d = t % 10;
        sum += (int)pow(d, digits); // integer power
        t /= 10;
    }
    printf("%d is %sArmstrong\n", n, (sum == n) ? "" : "not ");

    // ---------- Perfect ----------
    int divisorSum = 0;
    for (int i = 1; i <= n/2; ++i) {
        if (n % i == 0) divisorSum += i;
    }
    printf("%d is %sperfect\n", n, (divisorSum == n) ? "" : "not ");

    // ---------- Sum of digits ----------
    int digitSum = 0; t = n;
    while (t > 0) { digitSum += t % 10; t /= 10; }
    printf("Sum of digits of %d = %d\n", n, digitSum);

    // ---------- GCD & LCM ----------
    int a, b; // ask for a second number
    printf("Enter second integer for GCD/LCM: ");
    scanf("%d", &b);
    a = n; // reuse first number as a
    int x = a, y = b; // copy for Euclid
    while (y != 0) {
        int r = x % y;
        x = y;
        y = r;
    }
    int gcd = x;
    long long lcm = (long long)a * b / gcd;
    printf("GCD(%d,%d) = %d, LCM = %lld\n", a, b, gcd, lcm);

    return 0;
}

