#include <stdio.h>
#define SIZE 8

int main() {
    int a[SIZE] = {5, 2, 9, 1, 7, 3, 8, 4};
    int len = SIZE; // logical size
    int i, temp, max, min, sum = 0;

    // 1. Find max and min
    max = min = a[0];
    for(i = 1; i < len; ++i) {
        if(a[i] > max) max = a[i];
        if(a[i] < min) min = a[i];
    }
    printf("Max=%d Min=%d\n", max, min);

    // 2. Sum of elements
    for(i = 0; i < len; ++i) sum += a[i];
    printf("Sum=%d\n", sum);

    // 3. Reverse array in‑place
    for(i = 0; i < len/2; ++i) {
        temp = a[i];
        a[i] = a[len-1-i];
        a[len-1-i] = temp;
    }
    printf("Reversed: ");
    for(i = 0; i < len; ++i) printf("%d ", a[i]);
    printf("\n");

    // 4. Insert 99 at index 3 (shift right)
    int insertIdx = 3, val = 99;
    if(len < SIZE) { // ensure space
        for(i = len; i > insertIdx; --i) a[i] = a[i-1];
        a[insertIdx] = val;
        ++len;
    }
    printf("After insert: ");
    for(i = 0; i < len; ++i) printf("%d ", a[i]);
    printf("\n");

    // 5. Delete element at index 5 (shift left)
    int delIdx = 5;
    for(i = delIdx; i < len-1; ++i) a[i] = a[i+1];
    --len;
    printf("After delete: ");
    for(i = 0; i < len; ++i) printf("%d ", a[i]);
    printf("\n");
    return 0;
}

