#include <stdio.h>
#define MAX 10

int main(){
    int r,c, i, j, k;
    int A[MAX][MAX], B[MAX][MAX], C[MAX][MAX];
    // Input dimensions (assume square for simplicity)
    printf("Enter size of square matrices: ");
    scanf("%d", &r);
    c = r;
    // Input matrix A
    printf("Enter elements of matrix A:\n");
    for(i=0;i<r;i++)
        for(j=0;j<c;j++)
            scanf("%d", &A[i][j]);
    // Input matrix B
    printf("Enter elements of matrix B:\n");
    for(i=0;i<r;i++)
        for(j=0;j<c;j++)
            scanf("%d", &B[i][j]);
    // 1) Addition
    for(i=0;i<r;i++)
        for(j=0;j<c;j++)
            C[i][j] = A[i][j] + B[i][j];
    printf("\nMatrix Addition (A+B):\n");
    for(i=0;i<r;i++){
        for(j=0;j<c;j++)
            printf("%4d", C[i][j]);
        printf("\n");
    }
    // 2) Multiplication (A*B)
    for(i=0;i<r;i++)
        for(j=0;j<c;j++){
            int sum = 0;
            for(k=0;k<c;k++)
                sum += A[i][k] * B[k][j];
            C[i][j] = sum;
        }
    printf("\nMatrix Multiplication (A*B):\n");
    for(i=0;i<r;i++){
        for(j=0;j<c;j++)
            printf("%4d", C[i][j]);
        printf("\n");
    }
    // 3) Transpose of A
    printf("\nTranspose of A:\n");
    for(i=0;i<r;i++){
        for(j=0;j<c;j++)
            printf("%4d", A[j][i]); // note swapped indices
        printf("\n");
    }
    // 4) Diagonal sum of A (main diagonal)
    int diagSum = 0;
    for(i=0;i<r;i++)
        diagSum += A[i][i];
    printf("\nSum of main diagonal of A = %d\n", diagSum);
    return 0;
}
// Important lines: nested loops for each operation; reset accumulator `sum` for multiplication; transpose uses swapped indices.

