bool isPalindrome(const char *s) {
    size_t len = strlen(s);
    size_t i = 0, j = len - 1;
    while (i < j) {
        while (i < j && !isalpha((unsigned char)s[i])) i++;
        while (i < j && !isalpha((unsigned char)s[j])) j--;
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)s[j]))
            return false;
        i++; j--;
    }
    return true;
}

