char* concat(const char *a, const char *b) {
    size_t la = strlen(a), lb = strlen(b);
    char *res = malloc(la + lb + 1);
    if (!res) return NULL;
    strcpy(res, a);
    strcat(res, b);
    return res;
}

#include <stddef.h>
char* find_substring(const char *text, const char *pattern) {
    if (!*pattern) return (char*)text; // empty pattern
    for (const char *p = text; *p; ++p) {
        const char *t = p, *q = pattern;
        while (*t && *q && *t == *q) { ++t; ++q; }
        if (!*q) return (char*)p; // full match
    }
    return NULL;
}

