#include <stdio.h>

// compute length without library
int str_len(const char *s){
    int i=0; while(s[i]!='\0') i++; return i;
}

// copy source to dest
void str_copy(char *dest, const char *src){
    int i=0; while((dest[i]=src[i])!='\0') i++; // copy including '\0'
}

// reverse in place
void str_reverse(char *s){
    int i=0, j=str_len(s)-1; // j points to last character
    while(i<j){
        char tmp=s[i]; s[i]=s[j]; s[j]=tmp; i++; j--; // swap
    }
}

// palindrome check
int is_palindrome(const char *s){
    int i=0, j=str_len(s)-1;
    while(i<j){ if(s[i]!=s[j]) return 0; i++; j--; }
    return 1;
}

// count vowels (case‑insensitive)
int count_vowels(const char *s){
    int cnt=0; int i=0; char c;
    while((c=s[i++])!='\0'){
        if(c>='A' && c<='Z') c+=32; // to lower case
        if(c=='a'||c=='e'||c=='i'||c=='o'||c=='u') cnt++;
    }
    return cnt;
}

int main(){
    char s[100];
    printf("Enter a string: ");
    scanf("%99s", s); // reads up to whitespace
    printf("Length = %d\n", str_len(s));
    char copy[100];
    str_copy(copy, s);
    printf("Copy = %s\n", copy);
    str_reverse(s);
    printf("Reversed = %s\n", s);
    printf("Palindrome? %s\n", is_palindrome(copy)?"Yes":"No");
    printf("Vowels = %d\n", count_vowels(copy));
    return 0;
}

