void permute(char *a, int l, int r) {
    if (l == r) {
        printf("%s\n", a);
        return;
    }
    for (int i = l; i <= r; i++) {
        // swap
        char tmp = a[l]; a[l] = a[i]; a[i] = tmp;
        permute(a, l+1, r);
        // backtrack
        tmp = a[l]; a[l] = a[i]; a[i] = tmp;
    }
} // Call with permute(str, 0, strlen(str)-1);

