#include <stdio.h>

// Recursive factorial
int fact_rec(int n) {
    if (n <= 1) return 1;               // base case
    return n * fact_rec(n - 1);          // recursive call
}

// Iterative factorial
int fact_iter(int n) {
    int res = 1;
    for (int i = 2; i <= n; ++i) {
        res *= i;                        // update each iteration
    }
    return res;
}

int main() {
    int n = 5;
    printf("Recursive: %d\n", fact_rec(n)); // 120
    printf("Iterative: %d\n", fact_iter(n)); // 120
    return 0;
}

#include <stdio.h>
#include <stdlib.h>

// Recursive factorial – clear mathematical definition
unsigned long long factorial(int n) {
    if (n < 0) {
        fprintf(stderr, "Error: negative input\n");
        exit(EXIT_FAILURE);
    }
    if (n == 0) return 1ULL;          // base case
    return (unsigned long long)n * factorial(n - 1);
}

// Iterative factorial – efficient, no extra stack usage
unsigned long long factorial_iter(int n) {
    if (n < 0) {
        fprintf(stderr, "Error: negative input\n");
        exit(EXIT_FAILURE);
    }
    unsigned long long result = 1ULL;
    for (int i = 2; i <= n; ++i) {
        result *= (unsigned long long)i; // multiply step by step
    }
    return result;
}

int main(void) {
    int n = 5;
    printf("%d! (recursive) = %llu\n", n, factorial(n));
    printf("%d! (iterative) = %llu\n", n, factorial_iter(n));
    return 0;
}

