#include <stdio.h>
#include <stdlib.h>

// Ackermann function – careful with input size!
unsigned long long ackermann(unsigned int m, unsigned int n) {
    if (m == 0) return n + 1ULL;                     // base case
    if (n == 0) return ackermann(m - 1, 1ULL);       // second case
    return ackermann(m - 1, ackermann(m, n - 1));   // deep recursion
}

int main(void) {
    unsigned int m = 3, n = 4; // safe small values
    printf("Ackermann(%u,%u) = %llu\n", m, n, ackermann(m, n));
    return 0;
}
/* Important lines:
   - Two recursive calls in the last return make the stack grow extremely fast.
   - Use unsigned long long to hold results for small (m,n).
*/

