typedef struct {
    void **data;
    size_t top;
    size_t capacity;
} GStack;

GStack *gstack_create(size_t cap) {
    GStack *s = malloc(sizeof(GStack));
    s->data = malloc(cap * sizeof(void*));
    s->top = 0; s->capacity = cap; return s;
}
void gstack_push(GStack *s, void *elem) {
    if (s->top == s->capacity) return; // overflow check
    s->data[s->top++] = elem;
}
void *gstack_pop(GStack *s) {
    if (s->top == 0) return NULL; // underflow
    return s->data[--s->top];
}
// Caller must manage actual element memory.

