#include <stdio.h>

void bubble_sort(void *arr, size_t n, size_t sz, int (*cmp)(const void*, const void*)) {
    char *a = arr;
    for(size_t i=0;i<n-1;i++)
        for(size_t j=0;j<n-i-1;j++)
            if(cmp(a+j*sz, a+(j+1)*sz) > 0) {
                // swap
                for(size_t k=0;k<sz;k++) {
                    char tmp = a[j*sz+k];
                    a[j*sz+k] = a[(j+1)*sz+k];
                    a[(j+1)*sz+k] = tmp;
                }
            }
}

int int_cmp(const void *p, const void *q){
    int a = *(const int*)p, b = *(const int*)q;
    return (a>b) - (a<b);
}

int main(){
