#include <stdio.h>

struct Vector2D {
    float x;
    float y;
};

// Returned by value
struct Vector2D addVectors(struct Vector2D a, struct Vector2D b) {
    struct Vector2D result;
    result.x = a.x + b.x;
    result.y = a.y + b.y;
    return result;
}

// Passed by pointer to modify in-place
void scaleVector(struct Vector2D *v, float factor) {
    v->x *= factor;
    v->y *= factor;
}

// Passed by const pointer for read-only efficiency
void printVector(const struct Vector2D *v) {
    printf("Vector(%.2f, %.2f)\n", v->x, v->y);
}

int main(void) {
    struct Vector2D v1 = {2.0f, 3.5f};
    struct Vector2D v2 = {1.5f, 4.5f};

    struct Vector2D sum = addVectors(v1, v2);
    printf("Sum: ");
    printVector(&sum);

    scaleVector(&sum, 2.0f); // In-place modification
    printf("Scaled Sum: ");
    printVector(&sum);

    return 0;
}

