#include <stdio.h>
#include <stdlib.h>

// Self-referential structure definition
struct Node {
    int data;
    struct Node *next;
};

int main(void) {
    // Allocate two nodes dynamically on heap
    struct Node *first = (struct Node *)malloc(sizeof(struct Node));
    struct Node *second = (struct Node *)malloc(sizeof(struct Node));

    if (first == NULL || second == NULL) {
        printf("Memory allocation failed\n");
        return 1;
    }

    // Populate first node and link to second
    first->data = 10;
    first->next = second;

    // Populate second node and terminate with NULL
    second->data = 20;
    second->next = NULL;

    // Traverse using a temporary pointer
    struct Node *ptr = first;
    while (ptr != NULL) {
        printf("Node data: %d\n", ptr->data);
        ptr = ptr->next;
    }

    // Clean up heap memory
    free(first);
    free(second);
    return 0;
}

