#include <stdio.h>
#include <stddef.h>

// Badly ordered: heavy padding
struct BadOrder {
    char a;      // 1 byte
    // 3 bytes padding here
    int b;       // 4 bytes
    char c;      // 1 byte
    // 3 bytes tail padding
};

// Well ordered: descending sizes
struct GoodOrder {
    int b;       // 4 bytes
    char a;      // 1 byte
    char c;      // 1 byte
    // 2 bytes tail padding
};

int main(void) {
    printf("BadOrder size: %zu bytes\n", sizeof(struct BadOrder));
    printf("GoodOrder size: %zu bytes\n", sizeof(struct GoodOrder));
    printf("Offset of BadOrder.b: %zu\n", offsetof(struct BadOrder, b));
    printf("Offset of GoodOrder.c: %zu\n", offsetof(struct GoodOrder, c));
    return 0;
}

