// Original Layout:
// offset 0: char a (1 byte)
// offset 1-7: 7 padding bytes (double needs 8-byte alignment)
// offset 8-15: double d (8 bytes)
// offset 16-19: int i (4 bytes)
// offset 20-21: short s (2 bytes)
// offset 22-23: 2 tail padding bytes (to make total multiple of 8)
// Total Size = 24 bytes.

// Optimized Layout (descending order):
struct Optimized {
    double d; // offset 0 (8 bytes)
    int i;    // offset 8 (4 bytes)
    short s;  // offset 12 (2 bytes)
    char a;   // offset 14 (1 byte)
    // offset 15: 1 byte tail padding
};
// Optimized Size = 16 bytes (saved 8 bytes!).

