    int new_n = 5;
    int *temp = (int *)realloc(arr, new_n * sizeof(int));
    if (temp == NULL) {
        fprintf(stderr, "Reallocation failed! Original memory still intact.\n");
        free(arr); // Free original buffer before exiting
        return 1;
    }
    arr = temp; // Safe assignment

    // Initialize the newly added elements
    arr[3] = 40;
    arr[4] = 50;

    for (int i = 0; i < new_n; i++) {
        printf("%d ", arr[i]);
    }
    printf("\n");

    free(arr);
    arr = NULL;
    return 0;
}

