#include <stdio.h>
#include <stdlib.h>

typedef struct {
    int *data;
    size_t size;
    size_t capacity;
} Vector;

void init_vector(Vector *v) {
    v->size = 0;
    v->capacity = 2;
    v->data = malloc(v->capacity * sizeof(int));
}

void push_back(Vector *v, int val) {
    if (v->size == v->capacity) {
        size_t new_cap = v->capacity * 2;
        int *temp = realloc(v->data, new_cap * sizeof(int));
        if (!temp) {
            perror("realloc failed");
            return;
        }
        v->data = temp;
        v->capacity = new_cap;
    }
    v->data[v->size++] = val;
}

void free_vector(Vector *v) {
    free(v->data);
    v->data = NULL;
    v->size = v->capacity = 0;
}

