#include <stdio.h>
#include <stdlib.h>

char *read_line(void) {
    size_t cap = 16, len = 0;
    char *buf = malloc(cap);
    if (!buf) return NULL;
    int ch;
    while ((ch = getchar()) != '\n' && ch != EOF) {
        if (len + 1 >= cap) {
            cap *= 2;
            char *temp = realloc(buf, cap);
            if (!temp) {
                free(buf);
                return NULL;
            }
            buf = temp;
        }
        buf[len++] = (char)ch;
    }
    buf[len] = '\0';
    return buf;
}

