#include <stdio.h>
#include <stdlib.h>

void leaky_function(void) {
    int *data = (int *)malloc(100 * sizeof(int));
    // Memory is allocated on the heap.
    data[0] = 10;
    // Function ends: 'data' pointer variable is destroyed from the stack,
    // but the 400 bytes on the heap remain allocated! -> MEMORY LEAK
}

void clean_function(void) {
    int *data = (int *)malloc(100 * sizeof(int));
    if (data == NULL) return;
    data[0] = 10;
    // Clean up before exiting
    free(data);
    data = NULL;
}

int main(void) {
    printf("Calling clean function...\n");
    clean_function();
    printf("No leak occurred.\n");
    return 0;
}

