#include <stdio.h>

typedef struct {
    int id;
    double score;
} Record;

int main(void) {
    FILE *fp = fopen("records.bin", "wb+");
    if (!fp) return 1;

    Record r[3] = {{1, 10.5}, {2, 20.5}, {3, 30.5}};
    fwrite(r, sizeof(Record), 3, fp);

    // Jump directly to Record #2 (0-indexed: index 1)
    long offset = 1 * sizeof(Record);
    fseek(fp, offset, SEEK_SET);

    Record target;
    fread(&target, sizeof(Record), 1, fp);
    printf("Read Record 2 -> ID: %d, Score: %.1f\n", target.id, target.score);

    // Overwrite Record #2 in-place
    target.score = 99.9;
    fseek(fp, offset, SEEK_SET); // Seek back to record 2 start
    fwrite(&target, sizeof(Record), 1, fp);

    // Query file size using fseek and ftell
    fseek(fp, 0L, SEEK_END);
    long total_bytes = ftell(fp);
    printf("Total file size: %ld bytes (%zu records)\n",
           total_bytes, total_bytes / sizeof(Record));

    fclose(fp);
    return 0;
}

