    /* 3. Simple Interest Calculation */
    float principal = 10000.0f; /* Principal in Rupees */
    float rate = 7.5f;          /* Annual interest rate in % */
    float time = 3.0f;          /* Time in years */

    /* Division by 100.0f prevents integer division */
    float simple_interest = (principal * rate * time) / 100.0f;
    float total_amount = principal + simple_interest;

    printf("Circle Area (r=%.2f): %.2f\n", radius, circle_area);
    printf("Rectangle Area (%.2fx%.2f): %.2f\n", length, width, rect_area);
    printf("Simple Interest: Rs. %.2f (Total: Rs. %.2f)\n", simple_interest, total_amount);

    return 0;
}

