code.src:
#include <stdio.h>

void swap_temp(int *a, int *b) {
    int temp = *a;
    *a = *b;
    *b = temp;
}

void swap_arithmetic(int *a, int *b) {
    *a = *a + *b; // Risk of signed overflow if values are very large
    *b = *a - *b;
    *a = *a - *b;
}

void swap_xor(int *a, int *b) {
    if (a != b) { // Crucial guard against pointer aliasing
        *a ^= *b;
        *b ^= *a;
        *a ^= *b;
    }
}

int main(void) {
    int x = 10, y = 20;

    printf("Initial: x = %d, y = %d\n", x, y);
    swap_temp(&x, &y);
    printf("After temp swap: x = %d, y = %d\n", x, y);

    swap_arithmetic(&x, &y);
    printf("After arithmetic swap: x = %d, y = %d\n", x, y);

    swap_xor(&x, &y);
    printf("After XOR swap: x = %d, y = %d\n", x, y);

    return 0;
}

