void generic_swap(void *va, void *vb, size_t size) {
    if (va == vb || size == 0) return;
    unsigned char *a = (unsigned char *)va;
    unsigned char *b = (unsigned char *)vb;
    while (size--) {
        unsigned char tmp = *a;
        *a++ = *b;
        *b++ = tmp;
    }
}

