#include <stdio.h>
#include <stdbool.h>

bool is_even(int n) {
    return (n & 1) == 0; // Bitwise check avoids negative modulo sign issues
}

int largest_of_three(int a, int b, int c) {
    if (a >= b && a >= c) return a;
    if (b >= a && b >= c) return b;
    return c;
}

bool is_leap_year(int yr) {
    // Divisible by 400 OR (divisible by 4 but not 100)
    return (yr % 400 == 0) || (yr % 4 == 0 && yr % 100 != 0);
}

int main(void) {
    int num = -7;
    printf("%d is %s\n", num, is_even(num) ? "Even" : "Odd");

    int x = 45, y = 92, z = 73;
    printf("Largest of (%d, %d, %d) is %d\n", x, y, z, largest_of_three(x, y, z));

    int years[] = {1900, 2000, 2024};
    for (int i = 0; i < 3; i++) {
        printf("Year %d is %sa leap year\n", years[i], is_leap_year(years[i]) ? "" : "NOT ");
    }

    return 0;
}

