#include <stdio.h>
#include <math.h>

#define EPSILON 1e-9

void solve_quadratic(double a, double b, double c) {
    if (fabs(a) < EPSILON) {
        if (fabs(b) < EPSILON) {
            printf("Degenerate equation: no variable solutions.\n");
        } else {
            printf("Linear equation: Single root x = %.4lf\n", -c / b);
        }
        return;
    }

    double d = (b * b) - (4.0 * a * c);

    if (fabs(d) < EPSILON) { // d == 0
        double root = -b / (2.0 * a);
        printf("Roots are real and equal: x1 = x2 = %.4lf\n", root);
    } else if (d > 0.0) {
        double sqrt_d = sqrt(d);
        double r1 = (-b + sqrt_d) / (2.0 * a);
        double r2 = (-b - sqrt_d) / (2.0 * a);
        printf("Roots are real and distinct: x1 = %.4lf, x2 = %.4lf\n", r1, r2);
    } else {
        double real_pt = -b / (2.0 * a);
        double imag_pt = sqrt(-d) / (2.0 * a);
        printf("Roots are complex:\n");
        printf("x1 = %.4lf + %.4lfi\n", real_pt, fabs(imag_pt));
        printf("x2 = %.4lf - %.4lfi\n", real_pt, fabs(imag_pt));
    }
}

int main(void) {
    printf("Case 1 (D > 0):\n");
    solve_quadratic(1.0, -5.0, 6.0); // x^2 - 5x + 6 = 0

    printf("\nCase 2 (D == 0):\n");
    solve_quadratic(1.0, -4.0, 4.0); // x^2 - 4x + 4 = 0

    printf("\nCase 3 (D < 0):\n");
    solve_quadratic(1.0, 2.0, 5.0);  // x^2 + 2x + 5 = 0

    return 0;
}

