#include <stdio.h>
#include <math.h>

void stable_quadratic(double a, double b, double c, double *r1, double *r2) {
    double d = b * b - 4.0 * a * c;
    if (d < 0) return;
    double sgn_b = (b >= 0.0) ? 1.0 : -1.0;
    double q = -0.5 * (b + sgn_b * sqrt(d));
    *r1 = q / a;
    *r2 = c / q;
}

