#include <stdio.h>

int linearSearch(int arr[], int n, int key) {
    for (int i = 0; i < n; ++i) {
        if (arr[i] == key) return i; // found
    }
    return -1; // not found
}

int binarySearch(int arr[], int n, int key) {
    int low = 0, high = n - 1;
    while (low <= high) {
        int mid = low + (high - low) / 2; // avoid overflow
        if (arr[mid] == key) return mid; // found
        else if (arr[mid] < key) low = mid + 1; // search right half
        else high = mid - 1; // search left half
    }
    return -1; // not found
}

int main() {
    int data[] = {2, 4, 6, 8, 10, 12, 14, 16};
    int n = sizeof(data)/sizeof(data[0]);
    int key = 10;
    printf("Linear: %d\n", linearSearch(data, n, key)); // prints index 4
    printf("Binary: %d\n", binarySearch(data, n, key)); // prints index 4
    return 0;
}

