#include <stdio.h>

int main(void) {
    int r1, c1, r2, c2;
    printf("Enter rows and cols of Matrix A: ");
    scanf("%d %d", &r1, &c1);
    printf("Enter rows and cols of Matrix B: ");
    scanf("%d %d", &r2, &c2);

    // ----- Dimension checks -----
    if (r1 != r2 || c1 != c2) {
        printf("Addition not possible (different sizes).\n");
    }
    if (c1 != r2) {
        printf("Multiplication not possible (c1 != r2).\n");
    }

    // Using VLA (C99+). Adjust max size if your compiler lacks VLA support.
    int A[r1][c1], B[r2][c2];
    int Add[r1][c1];               // same size as A for addition
    int Mul[r1][c2];               // result size for multiplication

    // ----- Input matrices -----
    printf("Enter elements of Matrix A:\n");
    for (int i = 0; i < r1; ++i)
        for (int j = 0; j < c1; ++j)
            scanf("%d", &A[i][j]);

    printf("Enter elements of Matrix B:\n");
    for (int i = 0; i < r2; ++i)
        for (int j = 0; j < c2; ++j)
            scanf("%d", &B[i][j]);

    // ----- Addition -----
    if (r1 == r2 && c1 == c2) {
        for (int i = 0; i < r1; ++i)
            for (int j = 0; j < c1; ++j)
                Add[i][j] = A[i][j] + B[i][j];
        printf("\nMatrix Addition Result:\n");
        for (int i = 0; i < r1; ++i) {
            for (int j = 0; j < c1; ++j)
                printf("%d ", Add[i][j]);
            printf("\n");
        }
    }

    // ----- Multiplication -----
    if (c1 == r2) {
        for (int i = 0; i < r1; ++i) {
            for (int j = 0; j < c2; ++j) {
                int sum = 0; // reset for each cell
                for (int k = 0; k < c1; ++k)
                    sum += A[i][k] * B[k][j];
                Mul[i][j] = sum;
            }
        }
        printf("\nMatrix Multiplication Result:\n");
        for (int i = 0; i < r1; ++i) {
            for (int j = 0; j < c2; ++j)
                printf("%d ", Mul[i][j]);
            printf("\n");
        }
    }
    return 0;
}

