#include <stdio.h>

// Helper to compute length without strlen
int str_len(const char *s) {
    int len = 0;
    while (s[len] != '\0') len++; // count until null
    return len;
}

// Reverse in‑place
void str_rev(char *s) {
    int i = 0, j = str_len(s) - 1;
    while (i < j) {
        char tmp = s[i];
        s[i] = s[j];
        s[j] = tmp;
        i++; j--;
    }
}

// Palindrome test (case‑sensitive)
int is_palindrome(const char *s) {
    int i = 0, j = str_len(s) - 1;
    while (i < j) {
        if (s[i] != s[j]) return 0; // not palindrome
        i++; j--;
    }
    return 1; // palindrome
}

// Concatenate src to dest (dest must have enough space)
void str_concat(char *dest, const char *src) {
    int i = str_len(dest);
    int j = 0;
    while (src[j] != '\0') {
        dest[i++] = src[j++];
    }
    dest[i] = '\0'; // terminate
}

int main() {
    char s1[100] = "hello";
    char s2[100] = "world";

    printf("Length of s1: %d\n", str_len(s1));
    str_rev(s1);
    printf("Reversed s1: %s\n", s1);
    printf("Is \"madam\" palindrome? %s\n", is_palindrome("madam") ? "Yes" : "No");
    str_concat(s1, s2);
    printf("After concatenation: %s\n", s1);
    return 0;
}

