#include <stdio.h>

int main(void) {
    int low, high;
    printf("Enter range (low high): ");
    if (scanf("%d %d", &low, &high) != 2) {
        printf("Invalid input.\n");
        return 1;
    }

    printf("Primes between %d and %d are:\n", low, high);
    for (int num = low; num <= high; num++) {
        if (num < 2) {
            continue; // Numbers < 2 are not prime
        }

        int isPrime = 1;
        // Check divisors up to sqrt(num) using i * i <= num
        for (int i = 2; i * i <= num; i++) {
            if (num % i == 0) {
                isPrime = 0;
                break; // Found a factor, exit early
            }
        }

        if (isPrime) {
            printf("%d ", num);
        }
    }
    printf("\n");
    return 0;
}

